# ============================================================
#
# cross_dataset_disease_effect_scatter.R
#
# Compare the SAME "disease" contrast (e.g. control_vs_FA)
# already calculated independently in two datasets
# (e.g. iPSC vs iNeurons), to quantify whether the phenotype
# is more pronounced in one dataset compared with the other.
#
# DOES NOT RECALCULATE ANYTHING:
# directly reuses all_dataset_results as generated by main.R
#
# all_dataset_results[[dataset_name]][[contrast_name]]
# = res_df produced by run_deseq2_contrast,
# one result per dataset x contrast.
#
# To be called in main.R immediately after the
# "11. Cross-dataset comparison" section.
# Uses objects already available in memory and does not rerun analyses.
#
# ============================================================


run_disease_effect_scatter <- function(all_dataset_results,
                                       base_out,
                                       name_a          = "iPSC",
                                       name_b          = "iNeurons",
                                       contrasts       = c("control_vs_FA",
                                                           "control_vs_FA_edited",
                                                           "FA_edited_vs_FA"),
                                       padj_thr        = PADJ_THRESHOLD,
                                       lfc_thr         = LFC_THRESHOLD) {
  
  out_dir <- file.path(base_out, paste0("DiseaseEffect_", name_a, "_vs_", name_b))
  dir.create(out_dir, showWarnings = FALSE, recursive = TRUE)
  
  
  # ----------------------------------------------------------
  #
  # Standardizes a res_df:
  # ensures the presence of GENEID/GENENAME/log2FoldChange/padj,
  # and locally computes "sig" because the raw res_df returned
  # by run_deseq2_contrast may not contain this column yet
  # at this stage of the pipeline.
  #
  # ----------------------------------------------------------
  
  
  standardize_res_df <- function(res_df) {
    
    df <- as.data.frame(res_df)
    
    
    if (!"GENEID" %in% names(df)) {
      
      if (!is.null(rownames(df)) && any(grepl("^ENSG", rownames(df)))) {
        
        df <- tibble::rownames_to_column(df, "GENEID")
        
      } else {
        
        stop("Unable to find GENEID (neither as a column nor ENSG row names).")
        
      }
    }
    
    
    if (!"GENENAME" %in% names(df)) {
      
      df <- dplyr::left_join(df, gene_map, by = "GENEID")
      
    }
    
    
    df %>%
      dplyr::filter(!is.na(padj), !is.na(log2FoldChange)) %>%
      dplyr::mutate(
        sig = ifelse(
          padj < padj_thr &
            abs(log2FoldChange) >= lfc_thr,
          "Significant",
          "NS"
        )
      )
    
  }
  
  
  summary_rows <- list()
  
  
  for (cn in contrasts) {
    
    
    message("\n--- Cross-dataset disease effect ",
            name_a, " / ", name_b, " : ", cn, " ---")
    
    
    res_a_raw <- all_dataset_results[[name_a]][[cn]]
    res_b_raw <- all_dataset_results[[name_b]][[cn]]
    
    
    if (is.null(res_a_raw)) {
      message("  [SKIP] Missing contrast for ", name_a)
      next
    }
    
    if (is.null(res_b_raw)) {
      message("  [SKIP] Missing contrast for ", name_b)
      next
    }
    
    
    res_a <- standardize_res_df(res_a_raw)
    res_b <- standardize_res_df(res_b_raw)
    
    
    
    # ---- 1) Keep genes that are DEGs in AT LEAST one dataset ----
    
    
    df_a <- res_a %>%
      dplyr::select(GENEID, GENENAME, log2FoldChange, padj, sig) %>%
      dplyr::rename(
        lfc_a = log2FoldChange,
        padj_a = padj,
        sig_a = sig
      )
    
    
    df_b <- res_b %>%
      dplyr::select(GENEID, log2FoldChange, padj, sig) %>%
      dplyr::rename(
        lfc_b = log2FoldChange,
        padj_b = padj,
        sig_b = sig
      )
    
    
    df_merge <- dplyr::inner_join(df_a, df_b, by = "GENEID") %>%
      
      dplyr::filter(
        sig_a == "Significant" |
          sig_b == "Significant"
      ) %>%
      
      dplyr::mutate(
        sig_both = dplyr::case_when(
          
          sig_a == "Significant" &
            sig_b == "Significant" ~ "Both",
          
          sig_a == "Significant" ~ paste0("Only ", name_a),
          
          sig_b == "Significant" ~ paste0("Only ", name_b),
          
          TRUE ~ "NS"
          
        )
      )
    
    
    if (nrow(df_merge) < 10) {
      
      message(
        "  [SKIP] ",
        cn,
        ": too few DEG genes (n=",
        nrow(df_merge),
        ")"
      )
      
      next
    }
    
    
    
    
    # ---- 2) Correlation coefficient ----
    
    r_val  <- cor(
      df_merge$lfc_a,
      df_merge$lfc_b,
      use = "complete.obs"
    )
    
    r_test <- cor.test(
      df_merge$lfc_a,
      df_merge$lfc_b
    )
    
    
    
    # ---- 3) Linear regression: lfc_b ~ lfc_a ----
    #
    # slope = change in LFC(name_b) per unit of LFC(name_a)
    #
    # slope = 1  -> same effect magnitude in both datasets
    # slope > 1  -> stronger effect in name_b (Y axis)
    # slope < 1  -> weaker effect in name_b (Y axis)
    #
    
    fit <- lm(
      lfc_b ~ lfc_a,
      data = df_merge
    )
    
    
    slope     <- coef(fit)[["lfc_a"]]
    intercept <- coef(fit)[["(Intercept)"]]
    
    r_squared <- summary(fit)$r.squared
    
    slope_p <- summary(fit)$coefficients[
      "lfc_a",
      "Pr(>|t|)"
    ]
    
    
    # Relative difference in LFC amplitude between datasets
    pct_diff <- (slope - 1) * 100
    
    
    direction_txt <- if (slope > 1) {
      
      sprintf(
        "%s shows ~%.0f%% higher LFC amplitude than %s",
        name_b,
        pct_diff,
        name_a
      )
      
    } else {
      
      sprintf(
        "%s shows ~%.0f%% lower LFC amplitude than %s",
        name_b,
        abs(pct_diff),
        name_a
      )
      
    }
    
    
    
    message(
      sprintf(
        "  n=%d DEG genes (>=1 dataset) | r=%.3f (p=%.3g) | slope=%.3f (R²=%.3f, p=%.3g)",
        nrow(df_merge),
        r_val,
        r_test$p.value,
        slope,
        r_squared,
        slope_p
      )
    )
    
    
    message(
      "  -> ",
      direction_txt
    )
    
    
    
    summary_rows[[cn]] <- data.frame(
      
      contrast = cn,
      
      name_a = name_a,
      
      name_b = name_b,
      
      n_genes = nrow(df_merge),
      
      pearson_r = round(r_val, 3),
      
      r_pvalue = signif(r_test$p.value, 3),
      
      slope = round(slope, 3),
      
      intercept = round(intercept, 3),
      
      r_squared = round(r_squared, 3),
      
      slope_pvalue = signif(slope_p, 3),
      
      pct_diff_b_vs_a = round(pct_diff, 1)
      
    )
    
    
    
    # ---- Labels: all shared DEGs + top 50 dataset-specific DEGs ----
    
    # ---- Labels: all shared DEGs + top 50 genes most deviated from the regression line ----
    
    label_df <- df_merge %>%
      dplyr::mutate(
        max_abs_lfc = pmax(abs(lfc_a), abs(lfc_b)),
        predicted_b = predict(fit, newdata = df_merge),
        resid_b     = lfc_b - predicted_b,
        abs_resid   = abs(resid_b)
      )
    
    # Keep all genes significant in both datasets (unchanged: extrêmes conservés)
    label_both <- label_df %>%
      dplyr::filter(sig_a == "Significant" & sig_b == "Significant")
    
    # Top 50 genes significant in only one dataset,
    # selected by distance to the regression line (not raw LFC)
    label_only <- label_df %>%
      dplyr::filter(!(sig_a == "Significant" & sig_b == "Significant")) %>%
      dplyr::arrange(dplyr::desc(abs_resid)) %>%
      dplyr::slice_head(n = 50)
    
    # Final set of labels displayed on the plot
    label_df <- dplyr::bind_rows(label_both, label_only) %>%
      dplyr::distinct(GENEID, .keep_all = TRUE)
    
    
    # Keep all genes significant in both datasets
    
    label_both <- label_df %>%
      
      dplyr::filter(
        sig_a == "Significant" &
          sig_b == "Significant"
      )
    
    
    
    # Keep the top 50 genes significant in only one dataset
    
    label_only <- label_df %>%
      
      dplyr::filter(
        !(sig_a == "Significant" &
            sig_b == "Significant")
      ) %>%
      
      dplyr::arrange(
        dplyr::desc(max_abs_lfc)
      ) %>%
      
      dplyr::slice_head(n = 50)
    
    
    
    # Final set of labels displayed on the plot
    
    label_df <- dplyr::bind_rows(
      label_both,
      label_only
    ) %>%
      
      dplyr::distinct(
        GENEID,
        .keep_all = TRUE
      )
    
    
    
    if (nrow(label_df) > 150) {
      
      message(
        "  !! ",
        nrow(label_df),
        " labels will be displayed -- the plot may become crowded ",
        "(ggrepel overlaps)."
      )
      
    }
    
    
    
    # ---- Plot ----
    
    
    pdf(
      file.path(
        out_dir,
        paste0(
          "scatter_disease_effect_",
          cn,
          "_",
          name_a,
          "_vs_",
          name_b,
          ".pdf"
        )
      ),
      width = 10,
      height = 9
    )
    
    
    print(
      
      ggplot2::ggplot(
        df_merge,
        ggplot2::aes(
          x = lfc_a,
          y = lfc_b,
          color = sig_both
        )
      ) +
        
        ggplot2::geom_point(
          alpha = 0.5,
          size = 1.0
        ) +
        
        
        ggplot2::geom_smooth(
          ggplot2::aes(
            x = lfc_a,
            y = lfc_b
          ),
          inherit.aes = FALSE,
          data = df_merge,
          method = "lm",
          se = TRUE,
          color = "black",
          linewidth = 0.8
        ) +
        
        
        ggplot2::geom_abline(
          slope = 1,
          intercept = 0,
          linetype = "dotted",
          color = "grey30"
        ) +
        
        
        ggplot2::geom_hline(
          yintercept = 0,
          linetype = "dashed",
          color = "grey60"
        ) +
        
        
        ggplot2::geom_vline(
          xintercept = 0,
          linetype = "dashed",
          color = "grey60"
        ) +
        
        
        ggrepel::geom_label_repel(
          data = label_df,
          ggplot2::aes(
            label = GENENAME
          ),
          size = 2.6,
          max.overlaps = Inf,
          show.legend = FALSE
        ) +
        
        
        ggplot2::scale_color_manual(
          values = setNames(
            c(
              "#7b2d8b",
              "#2166ac",
              "#d6604d",
              "grey70"
            ),
            c(
              "Both",
              paste0("Only ", name_a),
              paste0("Only ", name_b),
              "NS"
            )
          )
        ) +
        
        
        # ---- Statistics annotation ----
      #
      # Displays:
      # - Pearson correlation coefficient
      # - Regression slope
      # - R²
      # - Number of genes included
      # - Relative LFC amplitude difference
      #
      
      ggplot2::annotate(
        "label",
        
        x = min(
          df_merge$lfc_a,
          na.rm = TRUE
        ),
        
        y = max(
          df_merge$lfc_b,
          na.rm = TRUE
        ),
        
        hjust = 0,
        
        vjust = 1,
        
        label = sprintf(
          paste0(
            "Pearson r = %.2f (p = %.2g)\n",
            "Slope = %.2f (R² = %.2f, p = %.2g)\n",
            "nGenes = %d\n",
            "%s"
          ),
          
          r_val,
          
          r_test$p.value,
          
          slope,
          
          r_squared,
          
          slope_p,
          
          nrow(df_merge),
          
          direction_txt
        ),
        
        size = 3,
        
        fill = "white",
        
        alpha = 0.85
        
      ) +
        
        
        
        ggplot2::theme_bw(
          base_size = 11
        ) +
        
        
        ggplot2::labs(
          
          title = paste0(
            "Disease effect: ",
            cn,
            " | ",
            name_a,
            " vs ",
            name_b
          ),
          
          subtitle =
            "Dotted line = y=x reference | Solid line = observed linear regression",
          
          x = paste0(
            "log2FC (",
            cn,
            ") ",
            name_a
          ),
          
          y = paste0(
            "log2FC (",
            cn,
            ") ",
            name_b
          ),
          
          color = NULL
          
        ) +
        
        
        ggplot2::theme(
          
          legend.position = "top"
          
        )
      
    )
    
    dev.off()
    
    
    
    # Export genes included in the comparison
    
    writexl::write_xlsx(
      
      df_merge,
      
      file.path(
        out_dir,
        paste0(
          "genes_",
          cn,
          "_",
          name_a,
          "_vs_",
          name_b,
          ".xlsx"
        )
      )
      
    )
    
    
  }
  
  
  
  # ----------------------------------------------------------
  #
  # Summary table:
  # correlation, slope, and relative LFC amplitude difference
  # for each contrast.
  #
  # Can be reused for additional comparisons:
  # Fibro vs iPSC / Fibro vs Neurons, etc.
  #
  # ----------------------------------------------------------
  
  
  summary_tab <- dplyr::bind_rows(
    summary_rows
  )
  
  
  
  if (nrow(summary_tab)) {
    
    
    write.csv(
      
      summary_tab,
      
      file.path(
        out_dir,
        paste0(
          "summary_slopes_",
          name_a,
          "_vs_",
          name_b,
          ".csv"
        )
      ),
      
      row.names = FALSE
      
    )
    
    
    message(
      "\n✔ Summary table (correlation, slope, % difference): ",
      
      file.path(
        out_dir,
        paste0(
          "summary_slopes_",
          name_a,
          "_vs_",
          name_b,
          ".csv"
        )
      )
      
    )
    
  }
  
  
  
  return(
    invisible(summary_tab)
  )
  
  
}
        
        
        
        
    



















